<?php
require_once __DIR__ . '/../database/app/layout.php';
$token=preg_replace('/[^a-f0-9]/i','',(string)($_GET['t']??''));
$q=db()->prepare("SELECT sf.id,sf.food_name,sf.category,sf.quantity_kg,sf.status,sf.safety_deadline,sf.storage_condition,sf.storage_method,sf.allergens,sf.cooked_time,u.name AS donor,sc.result AS safety_result,sc.checked_at,sc.reviewer_notes FROM surplus_food sf JOIN users u ON u.id=sf.restaurant_id LEFT JOIN food_safety_checks sc ON sc.surplus_food_id=sf.id WHERE sf.batch_token=? ORDER BY sc.created_at DESC LIMIT 1");
$q->execute([$token]);$f=$token!==''?$q->fetch():false; page_header('Food batch tracking');
?>
<div class="page-intro"><div class="eyebrow">BATCH TRACEABILITY</div><h1>Food batch <em>tracking.</em></h1><p>Scan the batch QR code to check the listing and recorded review status.</p></div>
<?php if(!$f): ?><div class="alert error">Batch not found. Check the QR code or contact the donor.</div><?php else: $expired=strtotime($f['safety_deadline'])<=time(); ?>
<div class="form-panel"><h2><?= e($f['food_name']) ?> · Batch #<?= (int)$f['id'] ?></h2><p><strong>Donor:</strong> <?= e($f['donor']) ?></p><p><strong>Listing status:</strong> <?= e($expired?'expired':$f['status']) ?></p><p><strong>Safety review:</strong> <?= e($f['safety_result']??'pending') ?></p><p><strong>Pickup deadline:</strong> <?= e(date('d M Y, g:i A',strtotime($f['safety_deadline']))) ?></p><p><strong>Storage declaration:</strong> <?= e($f['storage_condition']) ?> (<?= e($f['storage_method']??'unknown') ?>)</p><p><strong>Allergens:</strong> <?= e($f['allergens']?:'Not supplied') ?></p><?php if($f['checked_at']): ?><p><strong>Review time:</strong> <?= e(date('d M Y, g:i A',strtotime($f['checked_at']))) ?></p><?php endif; ?><div id="batch-qr" style="margin:18px 0"></div><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>if(window.QRCode){new QRCode(document.getElementById('batch-qr'),{text:location.href,width:180,height:180});}</script><div class="alert warning">A database status or QR page does not independently certify food safety. Verify actual handling, time and temperature before accepting food.</div></div>
<?php endif; ?><?php page_footer(); ?>
